CSS = '  /* ===================== Голо-экран ===================== */\n  .holo { position: absolute; right: 92px; top: 50%; transform: translateY(-50%); width: 300px; display: flex;\n    flex-direction: column; gap: 12px; z-index: 4; pointer-events: none; }\n  .hcard { pointer-events: auto; position: relative; padding: 10px 12px 12px; border-radius: 12px; color: var(--text);\n    background: linear-gradient(160deg, rgba(10,22,44,.74), rgba(4,8,18,.68)); border: 1px solid rgba(134,214,255,.22);\n    box-shadow: inset 0 0 0 1px rgba(134,214,255,.04), 0 10px 40px rgba(0,0,0,.45), 0 0 26px rgba(134,214,255,.08);\n    -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); cursor: zoom-in; overflow: hidden;\n    animation: hc-in .42s cubic-bezier(.2,.8,.2,1) both; }\n  .hcard::before { content: ""; position: absolute; inset: 0; pointer-events: none;\n    background: repeating-linear-gradient(0deg, rgba(134,214,255,.035) 0 1px, transparent 1px 3px); }\n  .hcard::after { content: ""; position: absolute; inset: 3px; pointer-events: none; border-radius: 10px;\n    background: linear-gradient(#86D6FF,#86D6FF) top left/12px 1px, linear-gradient(#86D6FF,#86D6FF) top left/1px 12px,\n      linear-gradient(#86D6FF,#86D6FF) bottom right/12px 1px, linear-gradient(#86D6FF,#86D6FF) bottom right/1px 12px;\n    background-repeat: no-repeat; opacity: .7; }\n  .hcard:hover, .hcard:focus-visible { border-color: rgba(134,214,255,.45); outline: none; }\n  .hcard.out { animation: hc-out .26s ease forwards; }\n  @keyframes hc-in { from { opacity: 0; transform: translateX(18px) scale(.96); filter: blur(4px); } to { opacity: 1; transform: none; filter: none; } }\n  @keyframes hc-out { to { opacity: 0; transform: translateX(14px) scale(.97); } }\n  .hc-head { display: flex; align-items: center; gap: 8px; font-size: 13px; margin-bottom: 8px; position: relative; z-index: 1; }\n  .hc-head b { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: .02em; font-weight: 600; }\n  .hc-ico { color: #86D6FF; display: flex; }\n  .hc-btn { width: 24px; height: 24px; display: grid; place-items: center; border-radius: 6px; cursor: pointer; color: var(--text);\n    border: 1px solid rgba(134,214,255,.18); background: rgba(134,214,255,.06); transition: background .15s; }\n  .hc-btn:hover { background: rgba(134,214,255,.18); }\n  .hc-img { border-radius: 8px; overflow: hidden; height: 168px; background: rgba(0,0,0,.3); }\n  .hc-img img { width: 100%; height: 100%; object-fit: cover; display: block; }\n  .hc-cap { margin: 8px 0 0; font-size: 12px; color: var(--muted); line-height: 1.45; display: -webkit-box;\n    -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n  .hc-wx { display: flex; align-items: center; gap: 12px; font-size: 13px; }\n  .hc-temp { font: 300 40px/1 "Exo 2", sans-serif; color: #EAF6FF; text-shadow: 0 0 18px rgba(134,214,255,.45); }\n  .hc-wx small, .wx-main small { display: block; color: var(--muted); font-size: 11.5px; margin-top: 2px; }\n  .hc-spark { width: 100%; height: 56px; display: block; margin-top: 6px; }\n  .hc-axis { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--muted); }\n  .holo-full { position: fixed; inset: 0; z-index: 60; display: grid; place-items: center; opacity: 0; pointer-events: auto;\n    background: rgba(2,4,10,.55); -webkit-backdrop-filter: blur(3px); backdrop-filter: blur(3px); transition: opacity .2s ease; }\n  .holo-full[hidden] { display: none; }\n  .holo-full.on { opacity: 1; }\n  .hf-panel { width: min(1280px, 88vw); height: min(860px, 84vh); display: flex; flex-direction: column; overflow: hidden;\n    border-radius: 14px; border: 1px solid rgba(134,214,255,.25); color: var(--text);\n    background: linear-gradient(160deg, rgba(8,18,38,.9), rgba(3,6,14,.92));\n    box-shadow: 0 30px 80px rgba(0,0,0,.6), 0 0 40px rgba(134,214,255,.1); transform: scale(.97);\n    transition: transform .22s cubic-bezier(.2,.8,.2,1); }\n  .holo-full.on .hf-panel { transform: none; }\n  .hf-head { display: flex; align-items: center; gap: 10px; padding: 12px 14px; font-size: 14px; border-bottom: 1px solid rgba(134,214,255,.12); }\n  .hf-head b { white-space: nowrap; font-weight: 600; letter-spacing: .02em; }\n  .hf-hint { flex: 1; color: var(--muted); font-size: 11.5px; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .hf-stage { position: relative; flex: 1; overflow: hidden; cursor: crosshair; touch-action: none; user-select: none;\n    background: radial-gradient(ellipse at center, rgba(134,214,255,.05), transparent 70%); }\n  .hf-stage.pan { cursor: grab; }\n  .hf-layer { position: absolute; left: 0; top: 0; transform-origin: 0 0; will-change: transform; }\n  .hf-layer img { display: block; width: 100%; height: 100%; -webkit-user-drag: none; }\n  .hf-ann { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; }\n  .hf-box { fill: rgba(134,214,255,.06); stroke: #86D6FF; stroke-width: 1.4; }\n  .hf-box.loading { stroke-dasharray: 5 4; animation: hf-dash 1s linear infinite; }\n  .hf-box.fail, .hf-lead.fail { stroke: #FFB35A; }\n  .hf-lead { fill: none; stroke: #86D6FF; stroke-width: 1.2; filter: drop-shadow(0 0 4px rgba(134,214,255,.7)); }\n  .hf-lead.fresh { stroke-dasharray: 700; stroke-dashoffset: 700; animation: hf-draw .45s ease forwards; }\n  .hf-dot { fill: #EAF6FF; filter: drop-shadow(0 0 4px #86D6FF); }\n  @keyframes hf-draw { to { stroke-dashoffset: 0; } }\n  @keyframes hf-dash { to { stroke-dashoffset: -18; } }\n  .hf-labels { position: absolute; inset: 0; pointer-events: none; }\n  .hf-note { position: absolute; left: 0; top: 0; width: 260px; pointer-events: auto; padding: 8px 10px 9px; border-radius: 8px;\n    background: rgba(4,10,24,.88); border: 1px solid rgba(134,214,255,.35); box-shadow: 0 0 18px rgba(134,214,255,.15);\n    font-size: 12.5px; color: #DDEBFF; animation: hc-in .35s ease both; }\n  .hf-note b { display: block; padding-right: 18px; color: #EAF6FF; font-size: 13px; letter-spacing: .02em; }\n  .hf-note p { margin: 4px 0 0; color: #AFC4E6; line-height: 1.45; }\n  .hf-note.loading b { background: linear-gradient(90deg, #6d8fb3, #EAF6FF, #6d8fb3); background-size: 200% 100%;\n    -webkit-background-clip: text; background-clip: text; color: transparent; animation: hf-shim 1.2s linear infinite; }\n  .hf-note.fail { border-color: rgba(255,179,90,.5); }\n  @keyframes hf-shim { to { background-position: -200% 0; } }\n  .hf-x { position: absolute; right: 6px; top: 3px; border: 0; background: none; color: var(--muted); cursor: pointer; font-size: 15px; }\n  .hf-x:hover { color: #EAF6FF; }\n  .hf-sel { position: absolute; left: 0; top: 0; border: 1px dashed #EAF6FF; background: rgba(134,214,255,.1);\n    box-shadow: 0 0 0 1px rgba(134,214,255,.3); pointer-events: none; }\n  .hf-foot { padding: 10px 14px; border-top: 1px solid rgba(134,214,255,.12); font-size: 12.5px; color: var(--muted); line-height: 1.45; }\n  .hf-wx { flex: 1; display: flex; flex-direction: column; padding: 14px 18px 18px; gap: 10px; min-height: 0; }\n  .wx-read { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 28px; min-height: 64px; }\n  .wx-when { font-size: 13px; color: var(--muted); display: flex; align-items: center; gap: 8px; }\n  .wx-tag { font-size: 10.5px; text-transform: uppercase; letter-spacing: .08em; padding: 2px 7px; border-radius: 4px; border: 1px solid; }\n  .wx-tag.now { color: #86D6FF; } .wx-tag.past { color: #8FA6CF; } .wx-tag.fut { color: #FFC478; }\n  .wx-main { display: flex; align-items: center; gap: 12px; font-size: 14px; }\n  .wx-meta { display: flex; gap: 18px; font-size: 13px; color: #C9D8F0; }\n  .wx-chart { flex: 1; width: 100%; min-height: 200px; cursor: ew-resize; touch-action: none; }\n  .wx-range { width: 100%; accent-color: #86D6FF; }\n  .wx-days { position: relative; height: 16px; font-size: 11px; color: var(--muted); }\n  .wx-days span { position: absolute; transform: translateX(-50%); white-space: nowrap; }\n  .wx-days span:first-child { transform: none; }\n  body[data-theme="light"] .hcard, body[data-theme="light"] .hf-panel { background: rgba(255,255,255,.9); color: #0E1A33; border-color: rgba(30,60,120,.2); }\n  body[data-theme="light"] .hc-temp { color: #0E1A33; text-shadow: none; }\n  @media (max-width: 1100px) { .holo { right: 16px; width: 260px; } }\n  @media (prefers-reduced-motion: reduce) { .hcard, .hf-note, .hf-lead.fresh { animation: none; stroke-dashoffset: 0; } }\n</style>\n'
